title:
// props drilling 문제
<Page user={user} avatarSize={avatarSize} />
  <PageLayout user={user} avatarSize={avatarSize} />
    <Avatar user={user} size={avatarSize} />  // 여기서만 사용

// 컴포넌트 자체를 내려보내기 (Inversion of Control)
function Page({ user, avatarSize }) {
  const userLink = <Avatar user={user} size={avatarSize} />
  return <PageLayout userLink={userLink} />
}
// PageLayout은 user를 알 필요 없음

