title:
// ✅ state에서 관리
class App extends React.Component {
  constructor(props) {
    super(props)
    this.state = { value: { something: 'something' } }
  }

  render() {
    return (
      <MyContext.Provider value={this.state.value}>
        <Toolbar />
      </MyContext.Provider>
    )
  }
}
// state는 실제로 바뀔 때만 새 참조 생성

